package edu.portal.web;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.nio.file.*; import java.util.*;
@Controller public class AnalyticsController { @Value("${portal.python.path}")String python; @Value("${portal.analysis.output}")String output; @GetMapping("/analytics")String page(Model m){try(var s=Files.list(Path.of(output))){m.addAttribute("charts",s.filter(p->p.toString().endsWith(".png")).map(p->p.getFileName().toString()).toList());}catch(Exception e){m.addAttribute("charts",List.of());}return "analytics";} @PostMapping("/analytics/regenerate")String regenerate(RedirectAttributes f){try{Process p=new ProcessBuilder(python,"main.py").directory(Path.of("..","python-analysis").toFile()).redirectErrorStream(true).start();if(!p.waitFor(90,java.util.concurrent.TimeUnit.SECONDS)||p.exitValue()!=0)throw new RuntimeException();f.addFlashAttribute("success","Charts regenerated.");}catch(Exception e){f.addFlashAttribute("error","Chart generation failed. Check Python dependencies and database/CSV configuration.");}return "redirect:/analytics";} }
